import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ProfService } from 'src/app/core/services/prof.service';

@Component({
  selector: 'app-classroom-list',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './classroom-list.component.html',
  styleUrls: ['./classroom-list.component.scss']
})
export class ClassroomListComponent implements OnInit {
  classes: any[] = [];
  newClass = { name: '', description: '' };
  msg = '';
  loading = false;

  constructor(private profService: ProfService) {}

  ngOnInit() {
    this.load();
  }

  load() {
    this.loading = true;
    this.profService.getMyClasses().subscribe({
      next: data => {
        this.classes = data;
        this.loading = false;
      },
      error: err => {
        console.error('Erreur chargement classes:', err);
        this.msg = '❌ Erreur lors du chargement des classes';
        this.loading = false;
      }
    });
  }

  create() {
    if (!this.newClass.name.trim()) {
      this.msg = '⚠️ Le nom est obligatoire';
      return;
    }

    this.profService.createClassroom(this.newClass).subscribe({
      next: () => {
        this.msg = '✅ Classe créée avec succès';
        this.newClass = { name: '', description: '' };
        this.load();
      },
      error: err => {
        console.error('Erreur création:', err);
        this.msg = '❌ Impossible de créer la classe';
      }
    });
  }
}
<section class="dashboard-container py-5">
  <div class="dashboard-header mb-4">
    <div>
      <h1 class="dashboard-title">Mes Classes</h1>
      <p class="dashboard-subtitle">Créez et gérez vos classes avec leur code d’accès unique</p>
    </div>
  </div>

  <div class="row g-4">
    <!-- Formulaire création -->
    <div class="col-lg-4 col-12">
      <div class="card p-4 shadow-sm">
        <h5 class="mb-3 fw-bold text-primary">➕ Nouvelle Classe</h5>

        <form (ngSubmit)="create()">
          <div class="mb-3">
            <label class="form-label">Nom de la classe</label>
            <input type="text" [(ngModel)]="newClass.name" name="name" class="form-control" required>
          </div>

          <div class="mb-3">
            <label class="form-label">Description</label>
            <textarea [(ngModel)]="newClass.description" name="description" class="form-control"></textarea>
          </div>

          <button type="submit" class="btn btn-primary w-100">Créer</button>
          <p class="text-center mt-2 text-muted">{{ msg }}</p>
        </form>
      </div>
    </div>

    <!-- Liste des classes -->
    <div class="col-lg-8 col-12">
      <div class="card p-4 shadow-sm">
        <h5 class="fw-bold mb-3">📋 Vos classes</h5>

        <div *ngIf="loading" class="text-center my-4">
          <div class="spinner-border text-primary"></div>
        </div>

        <table *ngIf="!loading && classes.length" class="table table-bordered align-middle">
          <thead class="table-light">
            <tr>
              <th>Nom</th>
              <th>Code</th>
              <th>Description</th>
              <th>Créée le</th>
            </tr>
          </thead>
          <tbody>
            <tr *ngFor="let c of classes">
              <td>{{ c.name }}</td>
              <td><span class="badge bg-warning text-dark">{{ c.accessCode }}</span></td>
              <td>{{ c.description }}</td>
              <td>{{ c.createdAt | date:'short' }}</td>
            </tr>
          </tbody>
        </table>

        <div *ngIf="!loading && !classes.length" class="alert alert-info text-center">
          Aucune classe trouvée.
        </div>
      </div>
    </div>
  </div>
</section>
